-- Seed User ID: 00000000-0000-0000-0000-000000000001

begin;

-- 0. Optional: Ensure system seed user placeholder exists in auth.users if foreign key is active
do $$
begin
  if exists (select 1 from information_schema.tables where table_schema = 'auth' and table_name = 'users') then
    if not exists (select 1 from auth.users where id = '00000000-0000-0000-0000-000000000001') then
      insert into auth.users (id, email, role, aud, created_at, updated_at)
      values ('00000000-0000-0000-0000-000000000001', 'catalog-seed@aegis.local', 'authenticated', 'authenticated', now(), now());
    end if;
  end if;
end $$;

